1	import React, { useEffect, useState } from 'react';
2	
3	// A project's invoices, rendered inside the projects feature when a project is opened. Lists the
4	// project's invoices, shows their derived total (amounts to 2 decimals), and adds a new invoice by
5	// amount. Owns its own state and data loading (no global store); composed, not branched.
6	type Invoice = { id: number; projectId: number; amount: number; status: string };
7	
8	function formatAmount(amount: number): string {
9	  return Number(amount).toFixed(2);
10	}
11	
12	export function ProjectInvoices({ projectId }: { projectId: number }) {
13	  const [invoices, setInvoices] = useState<Invoice[]>([]);
14	  const [amount, setAmount] = useState('');
15	
16	  async function load() {
17	    const res = await fetch(`/api/projects/${projectId}/invoices`);
18	    setInvoices(await res.json());
19	  }
20	
21	  useEffect(() => {
22	    void load();
23	  }, [projectId]);
24	
25	  async function onSubmit(e: React.FormEvent) {
26	    e.preventDefault();
27	    const res = await fetch(`/api/projects/${projectId}/invoices`, {
28	      method: 'POST',
29	      headers: { 'Content-Type': 'application/json' },
30	      body: JSON.stringify({ amount: Number(amount) }),
31	    });
32	    if (!res.ok) {
33	      return;
34	    }
35	    setAmount('');
36	    await load();
37	  }
38	
39	  async function pay(invoiceId: number) {
40	    const res = await fetch(`/api/invoices/${invoiceId}/pay`, { method: 'POST' });
41	    if (!res.ok) {
42	      return;
43	    }
44	    await load();
45	  }
46	
47	  const total = invoices.reduce((sum, inv) => sum + Number(inv.amount), 0);
48	
49	  return (
50	    <section data-testid="project-invoices">
51	      <h2>Invoices</h2>
52	
53	      <form data-testid="invoice-form" onSubmit={onSubmit}>
54	        <input
55	          data-testid="invoice-form-amount"
56	          placeholder="Amount"
57	          value={amount}
58	          onChange={(e) => setAmount(e.target.value)}
59	        />
60	        <button type="submit" data-testid="invoice-form-submit">
61	          Add invoice
62	        </button>
63	      </form>
64	
65	      <table data-testid="project-invoices-table">
66	        <thead>
67	          <tr>
68	            <th>Amount</th>
69	            <th>Status</th>
70	            <th></th>
71	          </tr>
72	        </thead>
73	        <tbody>
74	          {invoices.map((inv) => (
75	            <tr key={inv.id} data-testid={`invoice-row-${inv.id}`}>
76	              <td data-testid="invoice-amount">{formatAmount(inv.amount)}</td>
77	              <td data-testid="invoice-status">{inv.status}</td>
78	              <td>
79	                {inv.status === 'UNPAID' ? (
80	                  <button
81	                    type="button"
82	                    data-testid={`invoice-pay-${inv.id}`}
83	                    onClick={() => void pay(inv.id)}
84	                  >
85	                    Mark paid
86	                  </button>
87	                ) : null}
88	              </td>
89	            </tr>
90	          ))}
91	        </tbody>
92	        <tfoot>
93	          <tr>
94	            <td data-testid="project-invoices-total">{formatAmount(total)}</td>
95	          </tr>
96	        </tfoot>
97	      </table>
98	    </section>
99	  );
100	}
